const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Great Lakes geometry (bounding box)
  const greatLakes = ee.Geometry.Polygon([
    [[-92.5, 41.0], [-92.5, 49.0], [-76.0, 49.0], [-76.0, 41.0], [-92.5, 41.0]]
  ]);

  // 2. Define dates
  const date1 = '2021-02-20';
  const date2 = '2021-03-03';

  // 3. Load MODIS Terra Daily Snow Cover
  let col1 = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(greatLakes);

  let col2 = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(greatLakes);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Feb 20 images: ${size1}, Mar 3 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Trying Aqua MODIS (MYD10A1)...");
    col1 = ee.ImageCollection('MODIS/006/MYD10A1')
      .filterDate(date1, ee.Date(date1).advance(1, 'day'))
      .filterBounds(greatLakes);

    col2 = ee.ImageCollection('MODIS/006/MYD10A1')
      .filterDate(date2, ee.Date(date2).advance(1, 'day'))
      .filterBounds(greatLakes);

    const size1b = await col1.size().getInfo();
    const size2b = await col2.size().getInfo();

    console.log(`Aqua Feb 20: ${size1b}, Mar 3: ${size2b}`);

    if (size1b === 0 || size2b === 0) {
      console.log("No data available for one or both dates.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 4. Process images - mosaic if multiple tiles
  const img1 = col1.mosaic().select('NDSI_Snow_Cover');
  const img2 = col2.mosaic().select('NDSI_Snow_Cover');

  // 5. Mask invalid pixels (keep only 0-100 range for valid snow/ice coverage)
  const maskValid = function(img) {
    const mask = img.gte(0).and(img.lte(100));
    return img.updateMask(mask);
  };

  const img1Masked = maskValid(img1);
  const img2Masked = maskValid(img2);

  // 6. Calculate ice coverage (pixels with value >= 50 indicating ice/snow)
  const iceThreshold = 50;
  const ice1 = img1Masked.gte(iceThreshold);
  const ice2 = img2Masked.gte(iceThreshold);

  // 7. Count pixels
  const stats1 = await ice1.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: greatLakes,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await ice2.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: greatLakes,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const icePixels1 = stats1.NDSI_Snow_Cover_sum || 0;
  const totalPixels1 = stats1.NDSI_Snow_Cover_count || 0;
  const icePixels2 = stats2.NDSI_Snow_Cover_sum || 0;
  const totalPixels2 = stats2.NDSI_Snow_Cover_count || 0;

  console.log(`Feb 20: Ice pixels=${icePixels1}, Total valid=${totalPixels1}`);
  console.log(`Mar 3: Ice pixels=${icePixels2}, Total valid=${totalPixels2}`);

  // 8. Check for C2 (no valid pixels)
  if (totalPixels1 === 0 || totalPixels2 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 9. Calculate ice coverage percentage
  const iceCoverage1 = (icePixels1 / totalPixels1) * 100;
  const iceCoverage2 = (icePixels2 / totalPixels2) * 100;

  console.log(`Feb 20 ice coverage: ${iceCoverage1.toFixed(2)}%`);
  console.log(`Mar 3 ice coverage: ${iceCoverage2.toFixed(2)}%`);

  // 10. Check for C3 (invalid calculation)
  if (isNaN(iceCoverage1) || isNaN(iceCoverage2) || iceCoverage1 === null || iceCoverage2 === null) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 11. Determine if ice coverage decreased
  if (iceCoverage2 < iceCoverage1) {
    console.log("Ice coverage DECREASED from Feb 20 to Mar 3.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Ice coverage DID NOT decrease (stayed same or increased).");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
